<?php require 'config.php'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $q=$db->prepare('SELECT * FROM students WHERE email=?');$q->bind_param('s',$_POST['email']);$q->execute();$s=$q->get_result()->fetch_assoc();if($s&&password_verify($_POST['password'],$s['password'])){$_SESSION['student']=$s;header('Location: dashboard.php');exit;} $error='Invalid email or password.';} ?><!doctype html><html><head><title>Login</title><link rel="stylesheet" href="style.css"></head><body><main class="card"><h1>Login</h1><?php if($error): ?><p class="error"><?=e($error)?></p><?php endif; ?><form method="post"><input name="email" type="email" placeholder="Email" required><input name="password" type="password" placeholder="Password" required><button>Login</button></form><a href="register.php">Create account</a></main></body></html>
